		ContextActions:UnbindAction("phonk_delivery")
		ContextActions:UnbindAction("phonk_walk")
		ContextActions:UnbindAction("phonk_sprint")
		animator = nil
		tracks = {}
		currentTrack = nil
		figureRef = nil
		flingActive = false
		usingSkill = false
	end
	return m
end)
return modules
end)
if not ok then
    (warn or print)("[KernelPacker] failed to load UPDATED mind of him.lua: " .. tostring(result))
elseif type(result) == "table" and result ~= modules then
    for _, fn in ipairs(result) do table.insert(modules, fn) end
end
end

return modules
